import{createErrorId,createLogger}from"#internal/logging.js";import{toErrorMessage}from"#shared/errors.js";import{activeTurnId,turnPosition}from"#harness/session-machine/view.js";import{applyTransition,sessionView}from"#harness/session-machine/commit.js";import{fail}from"#harness/session-machine/transitions.js";import{isDynamicConnectionResolutionError}from"#context/dynamic-connection-lifecycle.js";const log=createLogger(`turn-step`);async function recoverDynamicConnectionRehydration(e){if(!isDynamicConnectionResolutionError(e.error))return;let t=createErrorId(),n=toErrorMessage(e.error);return log.error(`dynamic connection rehydration failed — parking session`,{error:e.error,errorId:t,sessionId:e.session.sessionId,turnId:activeTurnId(turnPosition(e.projection))}),{next:null,session:{...await applyTransition(e.session,fail(sessionView(e.projection,e.session.state),{code:`EVENT_HANDLER_FAILED`,details:{errorId:t},message:n}),e.emit),outputSchema:void 0},settledTurn:{isError:!0,output:n}}}export{recoverDynamicConnectionRehydration};