import{createLogger}from"#internal/logging.js";import{dispatchMemoryCompactionCompleted,dispatchMemoryCompactionRequested,dispatchMemoryTurnCompleted,dispatchMemoryTurnStarted}from"#context/memory-lifecycle.js";const log=createLogger(`memory`);async function dispatchMemoryLifecycleEvent(e){let t=e.messages??[];if(e.memories.length===0)return t;if(e.event.type===`turn.started`)return await dispatchMemoryTurnStarted({abortSignal:e.abortSignal,appRoot:e.appRoot,ctx:e.ctx,event:e.event,instrumentation:e.instrumentation,memories:e.memories,nodeId:e.nodeId});if(e.event.type===`compaction.requested`)await dispatchMemoryCompactionRequested({abortSignal:e.abortSignal,appRoot:e.appRoot,ctx:e.ctx,event:e.event,instrumentation:e.instrumentation,memories:e.memories,messages:t,nodeId:e.nodeId});else if(e.event.type===`compaction.completed`)t=await dispatchMemoryCompactionCompleted({abortSignal:e.abortSignal,ctx:e.ctx,event:e.event,instrumentation:e.instrumentation,memories:e.memories,messages:t});else if(e.event.type===`turn.completed`&&e.messages!==void 0)try{await dispatchMemoryTurnCompleted({abortSignal:e.abortSignal,ctx:e.ctx,event:e.event,instrumentation:e.instrumentation,memories:e.memories,messages:t})}catch(e){log.error(`Completed-turn memory capture failed.`,{error:e})}return t}export{dispatchMemoryLifecycleEvent};