const REMOTE_AGENT_PROTOCOL_VERSION=2,REMOTE_AGENT_PROTOCOL_MISMATCH=`REMOTE_AGENT_PROTOCOL_MISMATCH`,UNVERSIONED_REMOTE_AGENT_PROTOCOL=1;function readRemoteAgentProtocolVersion(e){return typeof e==`number`?e:1}function formatRemoteAgentProtocolMismatch(e){return`Remote agent "${e.name}" speaks eve remote agent protocol ${String(e.receiverVersion)}, but this deployment speaks protocol 2. Upgrade both deployments to the same eve release.`}export{REMOTE_AGENT_PROTOCOL_MISMATCH,REMOTE_AGENT_PROTOCOL_VERSION,UNVERSIONED_REMOTE_AGENT_PROTOCOL,formatRemoteAgentProtocolMismatch,readRemoteAgentProtocolVersion};