const rechecks=new WeakSet;function isApprovedToolCall(e,t){let n=new Set;for(let r of e)if(r.role===`assistant`&&typeof r.content!=`string`)for(let e of r.content)e.type===`tool-approval-request`&&e.toolCallId===t&&n.add(e.approvalId);return n.size!==0&&e.some(e=>e.role===`tool`&&e.content.some(e=>e.type===`tool-approval-response`&&e.approved&&n.has(e.approvalId)))}function markApprovalRecheck(e){return rechecks.add(e),e}function isApprovalRecheck(e){return rechecks.has(e)}export{isApprovalRecheck,isApprovedToolCall,markApprovalRecheck};