import{getSessionRemainingUsageQuota}from"#harness/turn-tag-state.js";function resolveRemainingSessionTokenLimits(e,t){let n=Math.max(1,t),r=getSessionRemainingUsageQuota(e),i={maxInputTokensPerSession:grantTokenShare(r.inputTokens,n),maxOutputTokensPerSession:grantTokenShare(r.outputTokens,n)};return r.costUsd!==!1&&(i.maxTokenCostUsdPerSession=r.costUsd/n),i}function grantTokenShare(e,t){return e!==!1&&Math.floor(e/t)}export{resolveRemainingSessionTokenLimits};