import{BundleKey}from"#runtime/sessions/runtime-context-keys.js";import{resolveEffectiveAgentRuntime}from"#execution/effective-agent-config.js";import{publishFromSessionStep,restoreSessionStep}from"#execution/publish-session-events.js";import{withSessionStateDelta}from"#execution/session/state-delta.js";import{bindSessionInstrumentation}from"#instrumentation/runtime.js";async function startTaskToolCallsStep(){"use step";return Date.now()}async function traceTaskToolCallStep(e,t){"use step";return await withSessionStateDelta(e,async e=>{let n=await restoreSessionStep(e),{published:r}=await publishFromSessionStep(n,{origin:`own`,async publish(e,r){await bindSessionInstrumentation({ctx:n.ctx,agentName:resolveEffectiveAgentRuntime(n.ctx.require(BundleKey),n.ctx).turnAgent.id,rootSessionId:r.rootSessionId??r.sessionId,sessionId:r.sessionId})?.instrumentTaskToolCall(t)}});return r})}export{startTaskToolCallsStep,traceTaskToolCallStep};